package com.cybershield.config;
import com.cybershield.model.*; import com.cybershield.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*;
@Configuration public class DataSeeder { @Bean @ConditionalOnProperty(name="app.demo.seed-enabled", havingValue="true") CommandLineRunner seed(UserRepository users,IncidentRepository incidents,PasswordEncoder enc){return args->{ if(users.count()==0){ User a=new User();a.setName("System Administrator");a.setEmail("admin@cybershield.local");a.setPassword(enc.encode("Admin@123"));a.setRole(Role.ADMIN);users.save(a); User an=new User();an.setName("Security Analyst");an.setEmail("analyst@cybershield.local");an.setPassword(enc.encode("Analyst@123"));an.setRole(Role.ANALYST);users.save(an); User u=new User();u.setName("Demo User");u.setEmail("user@cybershield.local");u.setPassword(enc.encode("User@123"));u.setRole(Role.USER);users.save(u); Incident i=new Incident();i.setTitle("Suspicious login attempts detected");i.setIncidentType("SUSPICIOUS_LOGIN");i.setSeverity("HIGH");i.setPriority("HIGH");i.setStatus("INVESTIGATING");i.setAffectedSystem("Identity Portal");i.setAffectedUsers("12 users");i.setDescription("Multiple failed sign-in attempts were detected from an unusual source.");i.setDetectedAt(LocalDateTime.now().minusHours(3));i.setReporter(a);i.setAssignee(an);incidents.save(i); } };} }
